import os, re, subprocess

entities = [
    "User", "Memo", "Attachment", "IdentityProvider", "Inbox", 
    "InstanceSetting", "MemoRelation", "MemoShare", "Reaction", 
    "UserIdentity", "UserSetting"
]

def get_package(filepath):
    """Get Go package path from file path"""
    # Use directory as package identifier
    rel = filepath.replace("./", "")
    if rel.startswith("store/"):
        return None
    return os.path.dirname(rel)

for entity in entities:
    pattern = rf'\bstore\.{entity}\b'
    result = subprocess.run(
        ['grep', '-r', pattern, '--include=*.go', '.'],
        capture_output=True, text=True, cwd='/bench/repo'
    )
    packages = set()
    for line in result.stdout.strip().split('\n'):
        if not line:
            continue
        filepath = line.split(':')[0]
        pkg = get_package(filepath)
        if pkg:
            packages.add(pkg)
    print(f"{entity}: {len(packages)} packages")
    for p in sorted(packages):
        print(f"  {p}")
    print()
PYEOF

